import React, { useState } from 'react';
import { PageContainer } from '@ant-design/pro-components';
import { Row, Col, Card, Table, Tag, Button, Space, Typography, Popconfirm, message, Tabs, Modal, Form, Input, Select, Switch } from 'antd';
import {
  StopOutlined, CheckCircleOutlined, UserAddOutlined, TeamOutlined,
  SafetyCertificateOutlined, UserOutlined, WarningOutlined,
  MailOutlined, PhoneOutlined, IdcardOutlined, LockOutlined,
} from '@ant-design/icons';
import { useModel } from '@umijs/max';

const { Title, Text } = Typography;

const AdminCustomers: React.FC = () => {
  const { users, toggleBanStatus, addUser } = useModel('adminUsers');
  const [activeTab, setActiveTab] = useState('all');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isActive, setIsActive] = useState(true);
  const [form] = Form.useForm();

  const totalUsers = users.length;
  const adminCount = users.filter(u => u.role === 'Quản trị').length;
  const activeCount = users.filter(u => u.status === 'active').length;
  const bannedCount = users.filter(u => u.status === 'banned').length;

  const filteredUsers = users.filter(u => {
    if (activeTab === 'admin') return u.role === 'Quản trị';
    if (activeTab === 'customer') return u.role === 'Khách hàng';
    return true;
  });

  const handleAddUser = (values: any) => {
    addUser({
      name: values.name,
      email: values.email,
      phone: values.phone,
      role: values.role,
    });
    message.success('Thêm người dùng thành công!');
    setIsModalOpen(false);
    form.resetFields();
    setIsActive(true);
  };

  const handleCancel = () => {
    setIsModalOpen(false);
    form.resetFields();
    setIsActive(true);
  };

  const columns = [
    {
      title: 'HỒ SƠ',
      dataIndex: 'name',
      key: 'name',
      render: (text: string, record: any) => (
        <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
          <div style={{
            width: 40, height: 40, borderRadius: '50%', background: 'linear-gradient(135deg, #059669, #00a67d)',
            color: 'white', display: 'flex', alignItems: 'center', justifyContent: 'center', fontWeight: 'bold', fontSize: 16,
          }}>
            {text.substring(0, 1)}
          </div>
          <div style={{ display: 'flex', flexDirection: 'column' }}>
            <Text strong style={{ color: '#1f2937' }}>{text}</Text>
            <Text type="secondary" style={{ fontSize: 12 }}>{record.email}</Text>
          </div>
        </div>
      )
    },
    {
      title: 'SỐ ĐIỆN THOẠI',
      dataIndex: 'phone',
      key: 'phone',
      render: (text: string) => <Text style={{ color: '#4b5563' }}>{text}</Text>
    },
    {
      title: 'VAI TRÒ',
      dataIndex: 'role',
      key: 'role',
      render: (role: string) => (
        <Tag color={role === 'Quản trị' ? 'blue' : 'default'} style={{ borderRadius: 12, padding: '2px 10px' }}>
          {role}
        </Tag>
      )
    },
    {
      title: 'TRẠNG THÁI',
      dataIndex: 'status',
      key: 'status',
      render: (status: string) => (
        <div style={{ display: 'flex', alignItems: 'center', gap: 6, color: status === 'active' ? '#059669' : '#dc2626', fontWeight: 600 }}>
          <div style={{ width: 8, height: 8, borderRadius: '50%', backgroundColor: status === 'active' ? '#059669' : '#dc2626' }} />
          {status === 'active' ? 'Hoạt động' : 'Bị chặn'}
        </div>
      )
    },
    {
      title: 'THAO TÁC',
      key: 'action',
      render: (_: any, record: any) => (
        <Space size="middle">
          <Popconfirm
            title={record.status === 'active' ? "Chặn người dùng này?" : "Bỏ chặn người dùng này?"}
            onConfirm={() => {
              toggleBanStatus(record.id);
              message.success(record.status === 'active' ? 'Đã chặn người dùng' : 'Đã bỏ chặn người dùng');
            }}
            okText="Đồng ý"
            cancelText="Hủy"
          >
            <Button danger={record.status === 'active'} type="text" icon={record.status === 'active' ? <StopOutlined /> : <CheckCircleOutlined />}>
              {record.status === 'active' ? 'Khóa' : 'Mở khóa'}
            </Button>
          </Popconfirm>
        </Space>
      )
    }
  ];

  // ─── Nội dung form bên phải ───────────────────────────────────────────────
  const formContent = (
    <Form form={form} layout="vertical" onFinish={handleAddUser} style={{ padding: '32px 32px 8px' }}>
      {/* Hàng 1: Họ tên + SĐT */}
      <Row gutter={16}>
        <Col span={12}>
          <Form.Item
            name="name"
            label={
              <span style={{ fontWeight: 600, color: '#374151', fontSize: 13, display: 'flex', alignItems: 'center', gap: 6 }}>
                <IdcardOutlined style={{ color: '#059669' }} /> Họ và tên
              </span>
            }
            rules={[{ required: true, message: 'Vui lòng nhập tên' }]}
          >
            <Input
              placeholder="Nguyễn Văn An"
              size="large"
              style={{ borderRadius: 10, borderColor: '#d1d5db' }}
            />
          </Form.Item>
        </Col>
        <Col span={12}>
          <Form.Item
            name="phone"
            label={
              <span style={{ fontWeight: 600, color: '#374151', fontSize: 13, display: 'flex', alignItems: 'center', gap: 6 }}>
                <PhoneOutlined style={{ color: '#059669' }} /> Số điện thoại
              </span>
            }
            rules={[{ required: true, message: 'Vui lòng nhập SĐT' }]}
          >
            <Input
              placeholder="0901 234 567"
              size="large"
              style={{ borderRadius: 10, borderColor: '#d1d5db' }}
            />
          </Form.Item>
        </Col>
      </Row>

      {/* Email */}
      <Form.Item
        name="email"
        label={
          <span style={{ fontWeight: 600, color: '#374151', fontSize: 13, display: 'flex', alignItems: 'center', gap: 6 }}>
            <MailOutlined style={{ color: '#059669' }} /> Địa chỉ Email
          </span>
        }
        rules={[{ required: true, type: 'email', message: 'Vui lòng nhập email hợp lệ' }]}
      >
        <Input
          placeholder="example@turfmanager.vn"
          size="large"
          style={{ borderRadius: 10, borderColor: '#d1d5db' }}
        />
      </Form.Item>

      {/* Vai trò + Trạng thái */}
      <Row gutter={16} align="bottom">
        <Col span={14}>
          <Form.Item
            name="role"
            initialValue="Khách hàng"
            label={
              <span style={{ fontWeight: 600, color: '#374151', fontSize: 13, display: 'flex', alignItems: 'center', gap: 6 }}>
                <UserOutlined style={{ color: '#059669' }} /> Vai trò
              </span>
            }
          >
            <Select size="large" style={{ borderRadius: 10 }}>
              <Select.Option value="Khách hàng">Khách hàng</Select.Option>
              <Select.Option value="Quản trị">Quản trị viên</Select.Option>
            </Select>
          </Form.Item>
        </Col>
        <Col span={10}>
          <Form.Item
            label={
              <span style={{ fontWeight: 600, color: '#374151', fontSize: 13, display: 'flex', alignItems: 'center', gap: 6 }}>
                <CheckCircleOutlined style={{ color: '#059669' }} /> Trạng thái
              </span>
            }
          >
            <div style={{ display: 'flex', alignItems: 'center', gap: 10, paddingBottom: 2 }}>
              <Switch
                checked={isActive}
                onChange={setIsActive}
                style={{ backgroundColor: isActive ? '#059669' : '#d1d5db' }}
              />
              <Text style={{ fontWeight: 600, color: isActive ? '#059669' : '#6b7280', fontSize: 14 }}>
                {isActive ? 'Đang hoạt động' : 'Không hoạt động'}
              </Text>
            </div>
          </Form.Item>
        </Col>
      </Row>

      {/* Mật khẩu */}
      <Form.Item
        name="password"
        label={
          <span style={{ fontWeight: 600, color: '#374151', fontSize: 13, display: 'flex', alignItems: 'center', gap: 6 }}>
            <LockOutlined style={{ color: '#059669' }} /> Mật khẩu mặc định
          </span>
        }
      >
        <Input.Password
          placeholder="Để trống để tự động tạo"
          size="large"
          style={{ borderRadius: 10, borderColor: '#d1d5db' }}
        />
      </Form.Item>

      {/* Footer */}
      <div style={{
        marginTop: 8, paddingTop: 20,
        borderTop: '1px solid #f3f4f6',
        display: 'flex', justifyContent: 'flex-end', gap: 12,
      }}>
        <Button
          size="large"
          onClick={handleCancel}
          style={{ borderRadius: 10, height: 44, padding: '0 24px', fontWeight: 600, color: '#374151', borderColor: '#d1d5db' }}
        >
          Hủy bỏ
        </Button>
        <Button
          type="primary"
          htmlType="submit"
          size="large"
          icon={<UserAddOutlined />}
          style={{
            backgroundColor: '#059669', borderColor: '#059669',
            borderRadius: 10, height: 44, padding: '0 28px', fontWeight: 700,
            boxShadow: '0 4px 12px rgba(5,150,105,0.3)',
          }}
        >
          Lưu thay đổi
        </Button>
      </div>
    </Form>
  );

  return (
    <PageContainer
      header={{
        title: (
          <div>
            <div style={{ fontWeight: 800, fontSize: 22, color: '#0f172a' }}>Quản lý Người dùng</div>
            <Text style={{ color: '#94a3b8', fontSize: 13 }}>Quản lý phân quyền, theo dõi hoạt động và cấu hình truy cập</Text>
          </div>
        ),
        extra: [
          <Button key="export" style={{ borderRadius: 10, height: 40, fontWeight: 600 }}>Xuất PDF</Button>,
          <Button key="add" type="primary" icon={<UserAddOutlined />} style={{ height: 40, padding: '0 20px', fontWeight: 700 }} onClick={() => setIsModalOpen(true)}>
            Thêm người dùng
          </Button>
        ]
      }}
    >
      <Row gutter={[16, 16]} style={{ marginBottom: 24 }}>
        <Col xs={24} sm={12} lg={6}>
          <div style={{ background: 'linear-gradient(135deg, #059669 0%, #047857 100%)', borderRadius: 16, padding: '20px 22px', color: 'white', boxShadow: '0 4px 20px rgba(5,150,105,0.25)', position: 'relative', overflow: 'hidden' }} className="admin-stat-card">
            <div style={{ position: 'absolute', right: -12, bottom: -12, width: 80, height: 80, borderRadius: '50%', backgroundColor: 'rgba(255,255,255,0.08)' }} />
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 14 }}>
              <div style={{ width: 40, height: 40, borderRadius: 10, backgroundColor: 'rgba(255,255,255,0.2)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <TeamOutlined style={{ fontSize: 20, color: '#fff' }} />
              </div>
              <div style={{ background: 'rgba(255,255,255,0.15)', padding: '3px 8px', borderRadius: 8, fontWeight: 700, fontSize: 11, color: '#a7f3d0' }}>+12% ↗</div>
            </div>
            <div style={{ color: 'rgba(255,255,255,0.75)', fontSize: 11, fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.06em', marginBottom: 4 }}>Tổng người dùng</div>
            <div style={{ fontSize: 28, fontWeight: 800, color: '#fff' }}>{totalUsers.toLocaleString()}</div>
          </div>
        </Col>
        <Col xs={24} sm={12} lg={6}>
          <div style={{ background: 'white', borderRadius: 16, padding: '20px 22px', border: '1px solid #e2e8f0', boxShadow: '0 1px 4px rgba(0,0,0,0.04)', position: 'relative', overflow: 'hidden' }} className="admin-stat-card">
            <div style={{ position: 'absolute', right: -12, bottom: -12, width: 80, height: 80, borderRadius: '50%', backgroundColor: '#e0e7ff18' }} />
            <div style={{ width: 40, height: 40, borderRadius: 10, backgroundColor: '#e0e7ff', color: '#4f46e5', display: 'flex', alignItems: 'center', justifyContent: 'center', marginBottom: 14 }}>
              <SafetyCertificateOutlined style={{ fontSize: 20 }} />
            </div>
            <div style={{ color: '#64748b', fontSize: 11, fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.06em', marginBottom: 4 }}>Quản trị viên</div>
            <div style={{ fontSize: 28, fontWeight: 800, color: '#0f172a' }}>{adminCount}</div>
          </div>
        </Col>
        <Col xs={24} sm={12} lg={6}>
          <div style={{ background: 'white', borderRadius: 16, padding: '20px 22px', border: '1px solid #e2e8f0', boxShadow: '0 1px 4px rgba(0,0,0,0.04)', position: 'relative', overflow: 'hidden' }} className="admin-stat-card">
            <div style={{ position: 'absolute', right: -12, bottom: -12, width: 80, height: 80, borderRadius: '50%', backgroundColor: '#dcfce718' }} />
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 14 }}>
              <div style={{ width: 40, height: 40, borderRadius: 10, backgroundColor: '#dcfce7', color: '#059669', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <UserOutlined style={{ fontSize: 20 }} />
              </div>
              <div style={{ background: '#dcfce7', padding: '3px 8px', borderRadius: 8, fontWeight: 700, fontSize: 11, color: '#15803d' }}>98% ↗</div>
            </div>
            <div style={{ color: '#64748b', fontSize: 11, fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.06em', marginBottom: 4 }}>Đang hoạt động</div>
            <div style={{ fontSize: 28, fontWeight: 800, color: '#0f172a' }}>{activeCount.toLocaleString()}</div>
          </div>
        </Col>
        <Col xs={24} sm={12} lg={6}>
          <div style={{ background: 'white', borderRadius: 16, padding: '20px 22px', border: '1px solid #e2e8f0', boxShadow: '0 1px 4px rgba(0,0,0,0.04)', position: 'relative', overflow: 'hidden' }} className="admin-stat-card">
            <div style={{ position: 'absolute', right: -12, bottom: -12, width: 80, height: 80, borderRadius: '50%', backgroundColor: '#fee2e218' }} />
            <div style={{ width: 40, height: 40, borderRadius: 10, backgroundColor: '#fee2e2', color: '#dc2626', display: 'flex', alignItems: 'center', justifyContent: 'center', marginBottom: 14 }}>
              <WarningOutlined style={{ fontSize: 20 }} />
            </div>
            <div style={{ color: '#64748b', fontSize: 11, fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.06em', marginBottom: 4 }}>Bị chặn</div>
            <div style={{ fontSize: 28, fontWeight: 800, color: '#dc2626' }}>{bannedCount}</div>
          </div>
        </Col>
      </Row>

      <Card bordered={false} bodyStyle={{ padding: '16px 24px', borderRadius: 12, boxShadow: '0 1px 2px rgba(0,0,0,0.05)' }}>
        <Tabs
          activeKey={activeTab}
          onChange={setActiveTab}
          items={[
            { key: 'all', label: 'Tất cả người dùng' },
            { key: 'admin', label: 'Quản trị viên' },
            { key: 'customer', label: 'Khách hàng' }
          ]}
          tabBarStyle={{ marginBottom: 0, borderBottom: '1px solid #f0f0f0' }}
        />
        <div style={{ paddingTop: 16 }}>
          <Table
            columns={columns}
            dataSource={filteredUsers}
            rowKey="id"
            pagination={{ pageSize: 5 }}
            className="custom-table"
          />
        </div>
      </Card>

      <Row gutter={[24, 24]} style={{ marginTop: 24 }}>
        <Col xs={24} lg={12}>
          <div style={{ padding: 24, backgroundColor: '#ecfdf5', borderRadius: 12, border: '1px solid #a7f3d0', display: 'flex', gap: 16 }}>
            <div style={{ width: 40, height: 40, backgroundColor: '#059669', color: 'white', borderRadius: 8, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 20 }}>
              i
            </div>
            <div>
              <div style={{ color: '#065f46', fontWeight: 700, marginBottom: 8, fontSize: 15 }}>Chính sách Quản lý Vai trò</div>
              <div style={{ color: '#047857', fontSize: 14, lineHeight: 1.5 }}>
                Lưu ý rằng việc thêm Quản trị viên mới yêu cầu xác minh hai bước. Tất cả thay đổi trạng thái (Chặn/Bỏ chặn) đều được ghi lại trong nhật ký hệ thống để tuân thủ bảo mật.
              </div>
            </div>
          </div>
        </Col>
        <Col xs={24} lg={12}>
          <Card bordered={false} bodyStyle={{ padding: 24, borderRadius: 12, border: '1px solid #f3f4f6' }}>
            <div style={{ fontSize: 16, fontWeight: 700, marginBottom: 16 }}>Hoạt động gần đây</div>
            <div style={{ display: 'flex', gap: 12, marginBottom: 16 }}>
              <div style={{ width: 32, height: 32, borderRadius: '50%', backgroundColor: '#e0e7ff', display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#4f46e5', fontWeight: 600 }}>JD</div>
              <div>
                <div style={{ fontSize: 14 }}><Text strong>John D.</Text> đã thêm Khách hàng mới</div>
                <div style={{ fontSize: 12, color: 'gray' }}>2 phút trước</div>
              </div>
            </div>
            <div style={{ display: 'flex', gap: 12 }}>
              <div style={{ width: 32, height: 32, borderRadius: '50%', backgroundColor: '#fee2e2', display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#dc2626' }}>
                <StopOutlined />
              </div>
              <div>
                <div style={{ fontSize: 14 }}><Text strong>Anita L.</Text> đã chặn người dùng Marcus K.</div>
                <div style={{ fontSize: 12, color: 'gray' }}>15 phút trước</div>
              </div>
            </div>
          </Card>
        </Col>
      </Row>

      {/* ── Modal Thêm người dùng – thiết kế 2 panel ── */}
      <Modal
        open={isModalOpen}
        onCancel={handleCancel}
        footer={null}
        width={700}
        style={{ top: 60 }}
        styles={{ body: { padding: 0 } }}
        closeIcon={
          <span style={{ fontSize: 18, color: '#9ca3af', lineHeight: 1 }}>✕</span>
        }
      >
        <div style={{ display: 'flex', borderRadius: 12, overflow: 'hidden', minHeight: 500 }}>
          {/* Panel trái – xanh lá */}
          <div style={{
            width: 200, minWidth: 200,
            background: 'linear-gradient(160deg, #059669 0%, #047857 100%)',
            padding: '36px 24px',
            display: 'flex', flexDirection: 'column', justifyContent: 'space-between',
          }}>
            <div>
              <div style={{
                width: 48, height: 48, borderRadius: 12,
                backgroundColor: 'rgba(255,255,255,0.2)',
                display: 'flex', alignItems: 'center', justifyContent: 'center',
                marginBottom: 20,
              }}>
                <UserAddOutlined style={{ fontSize: 24, color: '#fff' }} />
              </div>
              <div style={{ color: '#fff', fontSize: 18, fontWeight: 800, lineHeight: 1.3, marginBottom: 12 }}>
                Thông tin người dùng
              </div>
              <div style={{ color: 'rgba(255,255,255,0.75)', fontSize: 13, lineHeight: 1.6 }}>
                Vui lòng điền đầy đủ các thông tin bên dưới để cập nhật hệ thống.
              </div>
            </div>
            <div style={{
              padding: '12px 14px',
              backgroundColor: 'rgba(255,255,255,0.12)',
              borderRadius: 10, border: '1px solid rgba(255,255,255,0.15)',
            }}>
              <div style={{ color: 'rgba(255,255,255,0.7)', fontSize: 11, marginBottom: 4 }}>ℹ️ Lưu ý</div>
              <div style={{ color: '#fff', fontSize: 12, lineHeight: 1.5 }}>
                Quản trị viên mới yêu cầu xác minh hai bước.
              </div>
            </div>
          </div>

          {/* Panel phải – form */}
          <div style={{ flex: 1, backgroundColor: '#fff' }}>
            {formContent}
          </div>
        </div>
      </Modal>

    </PageContainer>
  );
};

export default AdminCustomers;

18.__content:
import React, { useState } from 'react';
import { PageContainer } from '@ant-design/pro-components';
import { Card, Table, Tag, Row, Col, DatePicker, Select, Space, Button, Typography } from 'antd';
import { PieChart, Pie, Cell, Tooltip, ResponsiveContainer, Legend, AreaChart, Area, XAxis, YAxis, CartesianGrid } from 'recharts';
import {
  DownloadOutlined, WalletOutlined, ArrowUpOutlined,
  TransactionOutlined, ReloadOutlined, CheckCircleOutlined,
} from '@ant-design/icons';
import dayjs from 'dayjs';
import axios from 'axios'; // We can use axios for this

const { RangePicker } = DatePicker;
const { Text } = Typography;

const transactionData = [
  { id: 'TXN001', date: '2026-05-09 18:30', user: 'Nguyễn Văn A', type: 'Đặt sân', amount: 450000, method: 'Chuyển khoản', status: 'success' },
  { id: 'TXN002', date: '2026-05-09 19:00', user: 'Nguyễn Văn A', type: 'Dịch vụ (Nước, Áo)', amount: 150000, method: 'Tiền mặt', status: 'success' },
  { id: 'TXN003', date: '2026-05-08 20:00', user: 'Trần B', type: 'Đặt sân', amount: 800000, method: 'Ví điện tử', status: 'refunded' },
  { id: 'TXN004', date: '2026-05-08 17:00', user: 'Lê C', type: 'Đặt sân', amount: 300000, method: 'Chuyển khoản', status: 'success' },
  { id: 'TXN005', date: '2026-05-07 19:30', user: 'FC Hàng Cuối', type: 'Đặt sân + Dịch vụ', amount: 650000, method: 'Tiền mặt', status: 'success' },
];

const revenueBreakdown = [
  { name: 'Tiền thuê sân', value: 45000000 },
  { name: 'Nước giải khát', value: 8500000 },
  { name: 'Thuê áo, bóng', value: 3200000 },
  { name: 'Tổ chức giải đấu', value: 12000000 },
];

const trendData = [
  { day: 'T2', revenue: 8400000 },
  { day: 'T3', revenue: 12000000 },
  { day: 'T4', revenue: 9500000 },
  { day: 'T5', revenue: 14000000 },
  { day: 'T6', revenue: 18000000 },
  { day: 'T7', revenue: 22000000 },
  { day: 'CN', revenue: 16000000 },
];

const COLORS = ['#059669', '#34d399', '#fbbf24', '#f87171'];

const METHOD_STYLES: Record<string, { bg: string; color: string; icon: string }> = {
  'Chuyển khoản': { bg: '#dbeafe', color: '#1d4ed8', icon: '🏦' },
  'Tiền mặt':     { bg: '#dcfce7', color: '#15803d', icon: '💵' },
  'Ví điện tử':   { bg: '#ede9fe', color: '#6d28d9', icon: '📱' },
};

const AdminFinance: React.FC = () => {
  const totalRevenue = 68700000;
  const totalTxn = transactionData.length;
  const successTxn = transactionData.filter(t => t.status === 'success').length;
  const refundedAmount = transactionData.filter(t => t.status === 'refunded').reduce((s, t) => s + t.amount, 0);

  const columns = [
    {
      title: 'Mã GD',
      dataIndex: 'id',
      key: 'id',
      render: (text: string) => (
        <span style={{
          fontFamily: 'monospace', fontSize: 12, fontWeight: 700,
          background: '#f1f5f9', padding: '3px 8px', borderRadius: 6, color: '#475569',
        }}>
          {text}
        </span>
      ),
    },
    {
      title: 'Khách hàng',
      dataIndex: 'user',
      key: 'user',
      render: (text: string) => (
        <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
          <div style={{
            width: 30, height: 30, borderRadius: '50%',
            background: 'linear-gradient(135deg, #059669, #34d399)',
            color: 'white', display: 'flex', alignItems: 'center', justifyContent: 'center',
            fontWeight: 700, fontSize: 11, flexShrink: 0,
          }}>
            {text.substring(0, 2).toUpperCase()}
          </div>
          <span style={{ fontWeight: 600, color: '#0f172a', fontSize: 13 }}>{text}</span>
        </div>
      ),
    },
    { title: 'Loại', dataIndex: 'type', key: 'type', render: (text: string) => <Text style={{ color: '#475569', fontSize: 13 }}>{text}</Text> },
    {
      title: 'Phương thức',
      dataIndex: 'method',
      key: 'method',
      render: (method: string) => {
        const cfg = METHOD_STYLES[method] || { bg: '#f1f5f9', color: '#475569', icon: '💳' };
        return (
          <div style={{
            display: 'inline-flex', alignItems: 'center', gap: 5,
            padding: '3px 10px', borderRadius: 20,
            backgroundColor: cfg.bg, color: cfg.color,
            fontWeight: 600, fontSize: 12,
          }}>
            {cfg.icon} {method}
          </div>
        );
      },
    },
    {
      title: 'Số tiền',
      dataIndex: 'amount',
      key: 'amount',
      render: (val: number, record: any) => (
        <div>
          <div style={{ fontWeight: 800, fontSize: 14, color: record.status === 'refunded' ? '#dc2626' : '#059669' }}>
            {record.status === 'refunded' ? '-' : '+'}{val.toLocaleString()}đ
          </div>
          <div style={{ fontSize: 10, color: '#cbd5e1' }}>{record.date}</div>
        </div>
      ),
    },
    {
      title: 'Trạng thái',
      dataIndex: 'status',
      key: 'status',
      render: (status: string) => {
        if (status === 'success') return (
          <div style={{ display: 'inline-flex', alignItems: 'center', gap: 5, padding: '4px 10px', borderRadius: 20, background: '#dcfce7', color: '#15803d', fontWeight: 700, fontSize: 11 }}>
            <CheckCircleOutlined /> Thành công
          </div>
        );
        if (status === 'refunded') return (
          <div style={{ display: 'inline-flex', alignItems: 'center', gap: 5, padding: '4px 10px', borderRadius: 20, background: '#fee2e2', color: '#dc2626', fontWeight: 700, fontSize: 11 }}>
            <ReloadOutlined /> Hoàn tiền
          </div>
        );
        return <Tag>Chờ xử lý</Tag>;
      },
    },
  ];

  return (
    <PageContainer
      header={{
        title: (
          <div>
            <div style={{ fontWeight: 800, fontSize: 22, color: '#0f172a' }}>Báo cáo & Tài chính</div>
            <Text style={{ color: '#94a3b8', fontSize: 13 }}>Theo dõi dòng tiền và phân tích cơ cấu doanh thu</Text>
          </div>
        ),
        extra: [
          <Button key="export" icon={<DownloadOutlined />} style={{ height: 40, fontWeight: 600, borderRadius: 10 }}>
            Xuất Excel
          </Button>,
        ],
      }}
    >
      {/* Summary Stats */}
      <Row gutter={[16, 16]} style={{ marginBottom: 24 }}>
        {[
          { icon: <WalletOutlined />, label: 'Tổng doanh thu', value: `${(totalRevenue / 1e6).toFixed(1)}M đ`, trend: '+14%', color: '#059669', bg: '#dcfce7', gradient: 'linear-gradient(135deg, #059669 0%, #047857 100%)' },
          { icon: <TransactionOutlined />, label: 'Giao dịch tháng này', value: `${totalTxn} GD`, trend: '+8%', color: '#2563eb', bg: '#dbeafe', gradient: undefined },
          { icon: <CheckCircleOutlined />, label: 'Thành công', value: `${successTxn} GD`, trend: `${Math.round(successTxn/totalTxn*100)}%`, color: '#7c3aed', bg: '#ede9fe', gradient: undefined },
          { icon: <ReloadOutlined />, label: 'Hoàn tiền', value: `${(refundedAmount/1000).toFixed(0)}K đ`, trend: '-2%', color: '#dc2626', bg: '#fee2e2', gradient: undefined },
        ].map((item, i) => (
          <Col xs={24} sm={12} lg={6} key={i}>
            <div style={{
              background: item.gradient || 'white',
              borderRadius: 16, padding: '20px 22px',
              border: item.gradient ? 'none' : '1px solid #e2e8f0',
              boxShadow: '0 1px 4px rgba(0,0,0,0.04)',
              position: 'relative', overflow: 'hidden',
              transition: 'transform 0.2s, box-shadow 0.2s',
            }} className="admin-stat-card">
              <div style={{ position: 'absolute', right: -12, bottom: -12, width: 80, height: 80, borderRadius: '50%', backgroundColor: item.gradient ? 'rgba(255,255,255,0.08)' : `${item.color}12` }} />
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 14 }}>
                <div style={{
                  width: 40, height: 40, borderRadius: 10,
                  background: item.gradient ? 'rgba(255,255,255,0.2)' : item.bg,
                  color: item.gradient ? '#fff' : item.color,
                  display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 18,
                }}>
                  {item.icon}
                </div>
                <div style={{
                  display: 'flex', alignItems: 'center', gap: 3,
                  color: item.gradient ? '#a7f3d0' : (item.trend.startsWith('+') ? '#059669' : '#dc2626'),
                  background: item.gradient ? 'rgba(255,255,255,0.15)' : (item.trend.startsWith('+') ? '#dcfce7' : '#fee2e2'),
                  padding: '3px 8px', borderRadius: 8, fontWeight: 700, fontSize: 11,
                }}>
                  {item.trend.startsWith('+') ? <ArrowUpOutlined /> : null}
                  {item.trend}
                </div>
              </div>
              <div style={{ color: item.gradient ? 'rgba(255,255,255,0.75)' : '#64748b', fontSize: 11, fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.06em', marginBottom: 4 }}>{item.label}</div>
              <div style={{ fontSize: 24, fontWeight: 800, color: item.gradient ? '#fff' : '#0f172a' }}>{item.value}</div>
            </div>
          </Col>
        ))}
      </Row>

      <Row gutter={[20, 20]}>
        {/* Pie Chart */}
        <Col xs={24} md={8}>
          <Card
            bordered={false}
            style={{ borderRadius: 16, border: '1px solid #e2e8f0', height: '100%', boxShadow: '0 1px 4px rgba(0,0,0,0.04)' }}
            bodyStyle={{ padding: 24 }}
          >
            <div style={{ marginBottom: 20 }}>
              <div style={{ fontWeight: 700, fontSize: 15, color: '#0f172a' }}>Cơ cấu doanh thu</div>
              <Text style={{ color: '#94a3b8', fontSize: 12 }}>Phân tích theo nguồn thu tháng này</Text>
            </div>
            <div style={{ height: 220 }}>
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={revenueBreakdown}
                    cx="50%" cy="50%"
                    innerRadius={55} outerRadius={80}
                    paddingAngle={4} dataKey="value"
                    stroke="none"
                  >
                    {revenueBreakdown.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                    ))}
                  </Pie>
                  <Tooltip formatter={(value) => `${Number(value).toLocaleString()}đ`} contentStyle={{ borderRadius: 10, border: 'none', fontSize: 12 }} />
                </PieChart>
              </ResponsiveContainer>
            </div>
            {/* Center label */}
            <div style={{ textAlign: 'center', marginTop: -8, marginBottom: 16 }}>
              <div style={{ fontSize: 22, fontWeight: 800, color: '#059669' }}>
                {(totalRevenue / 1e6).toFixed(1)}M đ
              </div>
              <div style={{ color: '#94a3b8', fontSize: 11, fontWeight: 600 }}>Tổng doanh thu</div>
            </div>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
              {revenueBreakdown.map((item, i) => (
                <div key={item.name} style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                  <div style={{ width: 10, height: 10, borderRadius: 3, backgroundColor: COLORS[i], flexShrink: 0 }} />
                  <span style={{ color: '#64748b', fontSize: 12, flex: 1 }}>{item.name}</span>
                  <span style={{ fontWeight: 700, color: '#0f172a', fontSize: 12 }}>{(item.value / 1e6).toFixed(1)}M</span>
                </div>
              ))}
            </div>
          </Card>
        </Col>

        {/* Area Chart + Table */}
        <Col xs={24} md={16}>
          {/* Trend chart */}
          <Card
            bordered={false}
            style={{ borderRadius: 16, border: '1px solid #e2e8f0', marginBottom: 20, boxShadow: '0 1px 4px rgba(0,0,0,0.04)' }}
            bodyStyle={{ padding: 24 }}
          >
            <div style={{ marginBottom: 16 }}>
              <div style={{ fontWeight: 700, fontSize: 15, color: '#0f172a' }}>Xu hướng doanh thu 7 ngày</div>
              <Text style={{ color: '#94a3b8', fontSize: 12 }}>Biến động doanh thu theo từng ngày trong tuần</Text>
            </div>
            <div style={{ height: 160 }}>
              <ResponsiveContainer width="100%" height="100%">
                <AreaChart data={trendData} margin={{ top: 5, right: 5, bottom: 0, left: 0 }}>
                  <defs>
                    <linearGradient id="areaGreen" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="0%" stopColor="#059669" stopOpacity={0.2} />
                      <stop offset="100%" stopColor="#059669" stopOpacity={0} />
                    </linearGradient>
                  </defs>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                  <XAxis dataKey="day" axisLine={false} tickLine={false} tick={{ fill: '#94a3b8', fontSize: 11, fontWeight: 600 }} />
                  <YAxis axisLine={false} tickLine={false} tick={{ fill: '#94a3b8', fontSize: 10 }} tickFormatter={v => `${(v/1e6).toFixed(0)}M`} />
                  <Tooltip formatter={(val: any) => [`${Number(val).toLocaleString()}đ`, 'Doanh thu']} contentStyle={{ borderRadius: 10, border: 'none', fontSize: 12 }} />
                  <Area type="monotone" dataKey="revenue" stroke="#059669" strokeWidth={2.5} fill="url(#areaGreen)" dot={{ fill: '#059669', strokeWidth: 0, r: 4 }} activeDot={{ r: 6 }} />
                </AreaChart>
              </ResponsiveContainer>
            </div>
          </Card>

          {/* Transaction Table */}
          <Card
            bordered={false}
            style={{ borderRadius: 16, border: '1px solid #e2e8f0', overflow: 'hidden', boxShadow: '0 1px 4px rgba(0,0,0,0.04)' }}
            bodyStyle={{ padding: 0 }}
          >
            <div style={{ padding: '16px 24px', borderBottom: '1px solid #f1f5f9', display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 12 }}>
              <div>
                <div style={{ fontWeight: 700, color: '#0f172a', fontSize: 15 }}>Lịch sử giao dịch</div>
                <Text style={{ color: '#94a3b8', fontSize: 12 }}>{transactionData.length} giao dịch gần nhất</Text>
              </div>
              <Space wrap>
                <RangePicker
                  defaultValue={[dayjs().subtract(7, 'days'), dayjs()]}
                  format="DD/MM/YYYY"
                  style={{ borderRadius: 8 }}
                />
                <Select defaultValue="all" style={{ width: 130 }} size="middle" options={[
                  { value: 'all', label: 'Tất cả TT' },
                  { value: 'success', label: 'Thành công' },
                  { value: 'refunded', label: 'Hoàn tiền' },
                ]} />
              </Space>
            </div>
            <Table
              columns={columns}
              dataSource={transactionData}
              rowKey="id"
              pagination={{ pageSize: 5, size: 'small' }}
              style={{ borderRadius: 0 }}
            />
          </Card>
        </Col>
      </Row>
    </PageContainer>
  );
};

export default AdminFinance;

19.__content:
import React, { useState } from 'react';
import { PageContainer } from '@ant-design/pro-components';
import {
  Table, Button, Space, Typography, Popconfirm, Tag, InputNumber,
  Modal, Form, Input, Select, Upload, message,
} from 'antd';
import {
  PlusOutlined, DeleteOutlined, EditOutlined, SaveOutlined,
  InboxOutlined, ShopOutlined, CoffeeOutlined, AppstoreOutlined,
  DollarOutlined, TagsOutlined, CheckCircleOutlined,
} from '@ant-design/icons';
import { useModel } from '@umijs/max';

const { Text } = Typography;
const { Dragger } = Upload;

const SERVICE_ICONS: Record<string, string> = {
  drink: '🧃',
  equipment: '⚽',
  food: '🍔',
  other: '📦',
};

const STATUS_CONFIG: Record<string, { label: string; bg: string; color: string }> = {
  in_stock: { label: 'Còn hàng', bg: '#dcfce7', color: '#15803d' },
  low_stock: { label: 'Sắp hết', bg: '#fef9c3', color: '#b45309' },
  out_of_stock: { label: 'Hết hàng', bg: '#fee2e2', color: '#dc2626' },
};

const AdminServices: React.FC = () => {
  const { services, deleteService, updateStock, addService } = useModel('adminServices');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingStock, setEditingStock] = useState<{ id: string; val: number } | null>(null);
  const [form] = Form.useForm();

  const handleAdd = (values: any) => {
    addService({
      name: values.name,
      type: values.type,
      price: values.price,
    });
    message.success('Đã thêm sản phẩm mới thành công!');
    setIsModalOpen(false);
    form.resetFields();
  };

  const totalItems = services.reduce((s, x) => s + x.stock, 0);
  const lowStockCount = services.filter(s => s.status === 'low_stock').length;
  const outStockCount = services.filter(s => s.status === 'out_of_stock').length;

  const columns = [
    {
      title: 'Sản phẩm / Dịch vụ',
      dataIndex: 'name',
      key: 'name',
      render: (text: string, record: any) => (
        <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
          <div style={{
            width: 42, height: 42, borderRadius: 12,
            backgroundColor: record.type === 'drink' ? '#dbeafe' : '#dcfce7',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            fontSize: 20, flexShrink: 0,
          }}>
            {SERVICE_ICONS[record.type] || '📦'}
          </div>
          <div>
            <div style={{ fontWeight: 700, color: '#0f172a', fontSize: 13.5 }}>{text}</div>
            <div style={{ fontSize: 11, color: '#94a3b8', marginTop: 2, fontWeight: 500 }}>
              {record.type === 'drink' ? '🧋 Đồ uống' : record.type === 'equipment' ? '🏟 Trang thiết bị' : '📦 Khác'}
            </div>
          </div>
        </div>
      ),
    },
    {
      title: 'Đơn giá',
      dataIndex: 'price',
      key: 'price',
      render: (price: number) => (
        <div>
          <div style={{ fontWeight: 700, color: '#059669', fontSize: 14 }}>{price.toLocaleString()}<span style={{ fontSize: 11, color: '#94a3b8', fontWeight: 500 }}> đ</span></div>
          <div style={{ fontSize: 11, color: '#cbd5e1', fontWeight: 500 }}>/ đơn vị</div>
        </div>
      ),
    },
    {
      title: 'Tồn kho',
      dataIndex: 'stock',
      key: 'stock',
      render: (stock: number, record: any) => (
        <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
          {editingStock?.id === record.id ? (
            <>
              <InputNumber
                min={0}
                value={editingStock?.val ?? 0}
                onChange={(val) => val !== null && setEditingStock({ id: record.id, val })}
                onPressEnter={() => {
                  if (editingStock) { updateStock(record.id, editingStock.val - stock); setEditingStock(null); }
                }}
                style={{ width: 90 }}
                size="small"
              />
              <SaveOutlined
                style={{ color: '#059669', cursor: 'pointer', fontSize: 16 }}
                onClick={() => {
                  if (editingStock) { updateStock(record.id, editingStock.val - stock); setEditingStock(null); }
                }}
              />
            </>
          ) : (
            <>
              <div style={{
                minWidth: 44, height: 32, borderRadius: 8,
                background: stock === 0 ? '#fee2e2' : stock < 10 ? '#fef9c3' : '#f0fdf4',
                color: stock === 0 ? '#dc2626' : stock < 10 ? '#b45309' : '#15803d',
                display: 'flex', alignItems: 'center', justifyContent: 'center',
                fontWeight: 800, fontSize: 14, padding: '0 10px',
              }}>
                {stock}
              </div>
              <EditOutlined
                style={{ color: '#94a3b8', cursor: 'pointer', fontSize: 14 }}
                onClick={() => setEditingStock({ id: record.id, val: stock })}
              />
            </>
          )}
        </div>
      ),
    },
    {
      title: 'Trạng thái',
      key: 'status',
      render: (_: any, record: any) => {
        const cfg = STATUS_CONFIG[record.status] || STATUS_CONFIG.out_of_stock;
        return (
          <div style={{
            display: 'inline-flex', alignItems: 'center', gap: 5,
            padding: '4px 12px', borderRadius: 20,
            backgroundColor: cfg.bg, color: cfg.color,
            fontWeight: 700, fontSize: 11,
          }}>
            <div style={{ width: 6, height: 6, borderRadius: '50%', backgroundColor: cfg.color }} />
            {cfg.label}
          </div>
        );
      },
    },
    {
      title: 'Thao tác',
      key: 'action',
      width: 80,
      render: (_: any, record: any) => (
        <Popconfirm
          title="Xóa sản phẩm này?"
          description="Hành động này không thể hoàn tác."
          onConfirm={() => { deleteService(record.id); message.success('Đã xóa!'); }}
          okText="Xóa"
          cancelText="Hủy"
          okButtonProps={{ danger: true }}
        >
          <Button
            danger icon={<DeleteOutlined />} type="text" size="small"
            style={{ borderRadius: 8 }}
          />
        </Popconfirm>
      ),
    },
  ];

  return (
    <PageContainer
      header={{
        title: (
          <div>
            <div style={{ fontWeight: 800, fontSize: 22, color: '#0f172a' }}>Quản lý Kho & Dịch vụ</div>
            <Text style={{ color: '#94a3b8', fontSize: 13 }}>Nước uống, bóng, áo sân cho thuê / bán tại sân</Text>
          </div>
        ),
        extra: [
          <Button
            key="add" type="primary" icon={<PlusOutlined />}
            onClick={() => setIsModalOpen(true)}
            style={{ height: 40, padding: '0 20px', fontWeight: 700 }}
          >
            Thêm sản phẩm
          </Button>,
        ],
      }}
    >
      {/* Top Summary */}
      <div style={{ display: 'flex', gap: 16, marginBottom: 24, flexWrap: 'wrap' }}>
        {[
          { icon: '📦', label: 'Tổng sản phẩm', value: services.length, color: '#0ea5e9', bg: '#e0f2fe' },
          { icon: '🔢', label: 'Tổng tồn kho', value: `${totalItems} đv`, color: '#059669', bg: '#dcfce7' },
          { icon: '⚠️', label: 'Sắp hết hàng', value: lowStockCount, color: '#b45309', bg: '#fef9c3' },
          { icon: '❌', label: 'Hết hàng', value: outStockCount, color: '#dc2626', bg: '#fee2e2' },
        ].map((item) => (
          <div key={item.label} style={{
            flex: '1 1 160px',
            background: 'white',
            borderRadius: 14,
            padding: '16px 20px',
            border: '1px solid #e2e8f0',
            display: 'flex', alignItems: 'center', gap: 12,
            boxShadow: '0 1px 4px rgba(0,0,0,0.04)',
          }}>
            <div style={{
              width: 40, height: 40, borderRadius: 10,
              backgroundColor: item.bg, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 18,
            }}>
              {item.icon}
            </div>
            <div>
              <div style={{ fontSize: 11, color: '#94a3b8', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.05em' }}>{item.label}</div>
              <div style={{ fontSize: 20, fontWeight: 800, color: item.color, lineHeight: 1.3 }}>{item.value}</div>
            </div>
          </div>
        ))}
      </div>

      {/* Table */}
      <div style={{
        background: 'white', borderRadius: 16,
        border: '1px solid #e2e8f0',
        boxShadow: '0 1px 4px rgba(0,0,0,0.04)',
        overflow: 'hidden',
      }}>
        <div style={{ padding: '18px 24px', borderBottom: '1px solid #f1f5f9', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <div style={{ fontWeight: 700, color: '#0f172a', fontSize: 15 }}>📋 Danh sách sản phẩm</div>
          <Text style={{ color: '#94a3b8', fontSize: 12 }}>{services.length} mục</Text>
        </div>
        <Table
          columns={columns}
          dataSource={services}
          rowKey="id"
          pagination={{ pageSize: 8, size: 'small' }}
          style={{ borderRadius: 0 }}
        />
      </div>

      {/* ─── Modal Thêm Sản Phẩm ─── */}
      <Modal
        open={isModalOpen}
        onCancel={() => { setIsModalOpen(false); form.resetFields(); }}
        footer={null}
        width={620}
        style={{ top: 80 }}
        styles={{ body: { padding: 0 } }}
        closeIcon={<span style={{ fontSize: 18, color: '#94a3b8' }}>✕</span>}
      >
        <div style={{ display: 'flex', borderRadius: 16, overflow: 'hidden', minHeight: 380 }}>
          {/* Panel trái */}
          <div style={{
            width: 180, minWidth: 180,
            background: 'linear-gradient(160deg, #059669 0%, #047857 100%)',
            padding: '36px 22px',
            display: 'flex', flexDirection: 'column', justifyContent: 'space-between',
          }}>
            <div>
              <div style={{
                width: 48, height: 48, borderRadius: 14,
                backgroundColor: 'rgba(255,255,255,0.2)',
                display: 'flex', alignItems: 'center', justifyContent: 'center',
                marginBottom: 20,
              }}>
                <ShopOutlined style={{ fontSize: 24, color: '#fff' }} />
              </div>
              <div style={{ color: '#fff', fontSize: 17, fontWeight: 800, lineHeight: 1.3, marginBottom: 10 }}>
                Thêm sản phẩm mới
              </div>
              <div style={{ color: 'rgba(255,255,255,0.75)', fontSize: 12.5, lineHeight: 1.6 }}>
                Bổ sung hàng hóa vào kho để phục vụ khách hàng tại sân.
              </div>
            </div>
            <div style={{
              padding: '12px 14px',
              backgroundColor: 'rgba(255,255,255,0.12)',
              borderRadius: 10, border: '1px solid rgba(255,255,255,0.15)',
            }}>
              <div style={{ color: 'rgba(255,255,255,0.7)', fontSize: 11, marginBottom: 4 }}>💡 Mẹo</div>
              <div style={{ color: '#fff', fontSize: 11.5, lineHeight: 1.5 }}>
                Cập nhật tồn kho thường xuyên để tránh hết hàng đột ngột.
              </div>
            </div>
          </div>

          {/* Panel phải */}
          <div style={{ flex: 1, backgroundColor: '#fff', padding: '32px 28px' }}>
            <Form form={form} layout="vertical" onFinish={handleAdd}>
              <Form.Item
                name="name"
                label={<span style={{ fontWeight: 600, color: '#374151', fontSize: 13, display: 'flex', alignItems: 'center', gap: 6 }}><TagsOutlined style={{ color: '#059669' }} /> Tên sản phẩm</span>}
                rules={[{ required: true, message: 'Nhập tên sản phẩm' }]}
              >
                <Input placeholder="Ví dụ: Nước suối Aquafina" size="large" style={{ borderRadius: 10 }} />
              </Form.Item>

              <Form.Item
                name="type"
                label={<span style={{ fontWeight: 600, color: '#374151', fontSize: 13, display: 'flex', alignItems: 'center', gap: 6 }}><AppstoreOutlined style={{ color: '#059669' }} /> Loại sản phẩm</span>}
                rules={[{ required: true, message: 'Chọn loại' }]}
                initialValue="drink"
              >
                <Select size="large" style={{ borderRadius: 10 }} options={[
                  { value: 'drink', label: '🧃 Đồ uống' },
                  { value: 'equipment', label: '⚽ Trang thiết bị' },
                  { value: 'food', label: '🍔 Đồ ăn nhanh' },
                  { value: 'other', label: '📦 Khác' },
                ]} />
              </Form.Item>

              <Form.Item
                name="price"
                label={<span style={{ fontWeight: 600, color: '#374151', fontSize: 13, display: 'flex', alignItems: 'center', gap: 6 }}><DollarOutlined style={{ color: '#059669' }} /> Đơn giá (VNĐ)</span>}
                rules={[{ required: true, message: 'Nhập đơn giá' }]}
              >
                <InputNumber
                  style={{ width: '100%', borderRadius: 10 }}
                  size="large"
                  formatter={v => `${v}`.replace(/\B(?=(\d{3})+(?!\d))/g, ',')}
                  parser={(v) => v!.replace(/,/g, '') as unknown as 0}
                  min={0}
                  step={1000}
                  placeholder="15,000"
                />
              </Form.Item>

              {/* Upload ảnh */}
              <Form.Item
                name="image"
                label={<span style={{ fontWeight: 600, color: '#374151', fontSize: 13, display: 'flex', alignItems: 'center', gap: 6 }}><InboxOutlined style={{ color: '#059669' }} /> Hình ảnh (tuỳ chọn)</span>}
              >
                <Dragger
                  name="file"
                  multiple={false}
                  beforeUpload={() => false}
                  style={{ borderRadius: 10 }}
                >
                  <p style={{ color: '#059669', fontSize: 24, marginBottom: 4 }}><InboxOutlined /></p>
                  <p style={{ color: '#374151', fontWeight: 600, fontSize: 13 }}>Kéo & thả ảnh vào đây</p>
                  <p style={{ color: '#94a3b8', fontSize: 11 }}>PNG, JPG tối đa 2MB</p>
                </Dragger>
              </Form.Item>

              <div style={{ paddingTop: 16, borderTop: '1px solid #f1f5f9', display: 'flex', justifyContent: 'flex-end', gap: 10 }}>
                <Button
                  size="large"
                  onClick={() => { setIsModalOpen(false); form.resetFields(); }}
                  style={{ borderRadius: 10, height: 44, padding: '0 22px', fontWeight: 600 }}
                >
                  Hủy
                </Button>
                <Button
                  type="primary" htmlType="submit" size="large"
                  icon={<CheckCircleOutlined />}
                  style={{ borderRadius: 10, height: 44, padding: '0 26px', fontWeight: 700, boxShadow: '0 4px 12px rgba(5,150,105,0.3)' }}
                >
                  Thêm sản phẩm
                </Button>
              </div>
            </Form>
          </div>
        </div>
      </Modal>
    </PageContainer>
  );
};

export default AdminServices;
